// Writes the theme CSS for each app from tokens.json. Run with `npm run tokens` after editing it.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const HEADER = `/*
 * Generated from tokens.json by generate.mjs. Do not edit this file.
 *
 * Spec 003 started from the Principal Design System (PDS) tokens; spec 005 moved the brand family
 * to a navy palette and added a dark palette (product owner decision, 2026-11-04). Mapping:
 * specs/003-shadcn-ai-elements/contracts/theme-tokens.md
 *
 * No Principal stylesheets, font files or logo are included (spec 003 FR-009).
 */
`;

const lines = (palette, indent, name) =>
  Object.entries(palette)
    .map(([key, value]) => `${indent}${name(key)}: ${value};`)
    .join("\n");

const colours = (palette) => Object.fromEntries(Object.entries(palette).filter(([key]) => key !== "radius"));

export function renderWeb({ light, dark }) {
  const web = (palette) => lines(palette, "  ", (key) => `--${key}`);
  return `${HEADER}:root {
  color-scheme: light;
${web(light)}
}

/* Dark palette: applied when <html> has the \`dark\` class, which follows the system setting. */
.dark {
  color-scheme: dark;
${web(dark)}
}
`;
}

export function renderNative({ light, dark }) {
  const native = (palette) => lines(colours(palette), "      ", (key) => `--color-${key}`);
  return `${HEADER}@layer theme {
  :root {
    @variant light {
${native(light)}
    }
    @variant dark {
${native(dark)}
    }
  }
}

@theme {
  --radius-lg: ${light.radius};
}
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const tokens = JSON.parse(readFileSync(new URL("./tokens.json", import.meta.url), "utf8"));
  mkdirSync(new URL("./generated/", import.meta.url), { recursive: true });
  writeFileSync(new URL("./generated/principal.css", import.meta.url), renderWeb(tokens));
  writeFileSync(new URL("./generated/uniwind.css", import.meta.url), renderNative(tokens));
}
